package httpmw

import (
	"regexp"
	"strings"

	"github.com/gin-gonic/gin"

	"github.com/cbl/cbl-kit/ginmw"
)

// requestIDPattern sets the allowed shape of a client request id.
var requestIDPattern = regexp.MustCompile(`^[A-Za-z0-9._-]{8,64}$`)

// SanitizeRequestID removes an unsafe client X-Request-Id before
// ginmw.RequestID: otherwise an arbitrary client string reaches the logs, the
// response and problem.request_id of all services (correlation spoofing, log
// pollution); an unsafe id is replaced with one generated by the perimeter.
func SanitizeRequestID() gin.HandlerFunc {
	return func(c *gin.Context) {
		id := strings.TrimSpace(c.GetHeader(ginmw.HeaderRequestID))
		if id != "" && !requestIDPattern.MatchString(id) {
			c.Request.Header.Del(ginmw.HeaderRequestID)
		}
		c.Next()
	}
}
